#!/bin/bash
# Claude Code Custom Status Line
# Generated by claude-statusline (npx claude-statusline)
# Layout: DIR [| WORKTREE] | BRANCH | CONTEXT | MODEL | COST | 5h-PLAN [| 7d-PLAN]

input=$(cat)

# ============================================================
# CONFIGURATION
# ============================================================
JIRA_BASE_URL="__JIRA_BASE_URL__"
JIRA_TICKET_PREFIX="__JIRA_TICKET_PREFIX__"
BAR_WIDTH=__BAR_WIDTH__
# When true, DIR shows the repo name and a linked worktree gets its own field.
# When false, DIR is the plain cwd basename and no worktree field is rendered.
SHOW_WORKTREE=__SHOW_WORKTREE__

# ============================================================
# COLORS
# ============================================================
C_RESET="\033[0m"
C_DIM="\033[0;90m"
C_MODEL="\033[0;90m"
C_DIR="__C_DIR__"
C_BRANCH="__C_BRANCH__"
C_WORKTREE="__C_WORKTREE__"
C_COST="\033[0;90m"
C_DIRTY="\033[38;5;214m"
C_BAR_OK="__C_BAR_OK__"
C_BAR_WARN="__C_BAR_WARN__"
C_BAR_CRIT="__C_BAR_CRIT__"
C_BAR_ALERT="__C_BAR_ALERT__"

# ============================================================
# SCRIPT
# ============================================================
model=$(echo "$input" | jq -r '.model.display_name // "Unknown"')
effort=$(echo "$input" | jq -r '.effort.level // empty')
[ -n "$effort" ] && model="${model}·${effort}"
cwd=$(echo "$input" | jq -r '.workspace.current_dir // ""')
used_pct=$(echo "$input" | jq -r '.context_window.used_percentage // empty')
cost=$(echo "$input" | jq -r '.cost.total_cost_usd // empty')
plan_pct=$(echo "$input" | jq -r '.rate_limits.five_hour.used_percentage // empty')
plan_resets_at=$(echo "$input" | jq -r '.rate_limits.five_hour.resets_at // empty')
week_pct=$(echo "$input" | jq -r '.rate_limits.seven_day.used_percentage // empty')
week_resets_at=$(echo "$input" | jq -r '.rate_limits.seven_day.resets_at // empty')

# --- Directory + Worktree ---
dir_name=""
wt_name=""
in_git=0
[ -n "$cwd" ] && dir_name=$(basename "$cwd")

if [ -n "$cwd" ] && git -C "$cwd" rev-parse --git-dir >/dev/null 2>&1; then
  in_git=1
  if [ "$SHOW_WORKTREE" = "true" ]; then
    # One call returns both paths; they are equal in a normal checkout and
    # differ only inside a linked worktree. Needs git 2.31+ for --path-format;
    # on older git this yields nothing and DIR keeps the plain cwd basename.
    git_paths=$(git -C "$cwd" --no-optional-locks rev-parse --path-format=absolute --git-dir --git-common-dir 2>/dev/null)
    if [ -n "$git_paths" ]; then
      git_dir=$(echo "$git_paths" | head -1)
      git_common=$(echo "$git_paths" | tail -1)
      # Repo name, so a linked worktree still says which project you're in.
      dir_name=$(basename "$(dirname "$git_common")")
      if [ "$git_dir" != "$git_common" ]; then
        wt_root=$(git -C "$cwd" --no-optional-locks rev-parse --show-toplevel 2>/dev/null)
        [ -n "$wt_root" ] && wt_name=$(basename "$wt_root")
        # Sibling worktrees are often named "<repo>-<thing>"; drop the repo
        # prefix so the field reads "docs" rather than "myrepo-docs".
        case "$wt_name" in
          "$dir_name"-*) wt_name="${wt_name#"$dir_name"-}" ;;
        esac
      fi
    fi
  fi
fi

# --- Git Branch + Dirty ---
branch=""
dirty=""
if [ "$in_git" -eq 1 ]; then
  branch=$(git -C "$cwd" --no-optional-locks rev-parse --abbrev-ref HEAD 2>/dev/null)
  if ! git -C "$cwd" --no-optional-locks diff --quiet 2>/dev/null || \
     ! git -C "$cwd" --no-optional-locks diff --cached --quiet 2>/dev/null; then
    dirty=" ${C_DIRTY}●${C_RESET}"
  fi
fi

# --- Context Progress Bar ---
ctx_str=""
if [ -n "$used_pct" ]; then
  used_int=${used_pct%.*}
  if [ "$used_int" -ge 80 ]; then
    bar_color="$C_BAR_CRIT"
  elif [ "$used_int" -ge 50 ]; then
    bar_color="$C_BAR_WARN"
  else
    bar_color="$C_BAR_OK"
  fi
  filled=$(( used_int * BAR_WIDTH / 100 ))
  empty=$(( BAR_WIDTH - filled ))
  bar=""
  for (( i=0; i<filled; i++ )); do bar="${bar}█"; done
  for (( i=0; i<empty; i++ )); do bar="${bar}░"; done
  ctx_str=$(printf "${bar_color}[%s] %d%%${C_RESET}" "$bar" "$used_int")
fi

# --- Cost ---
usage_str=""
if [ -n "$cost" ] && [ "$cost" != "null" ]; then
  cost_fmt=$(awk "BEGIN {printf \"%.2f\", $cost}")
  usage_str=$(printf "${C_COST}\$%s${C_RESET}" "$cost_fmt")
fi

# --- Plan Usage helper: render_plan <label> <pct> <resets_at> <color> <warn_secs> <crit_secs> <alert_secs> ---
render_plan() {
  local label="$1" pct="$2" resets_at="$3" color="$4" warn_secs="$5" crit_secs="$6" alert_secs="$7"
  [ -z "$pct" ] && return
  local pct_int=${pct%.*} bar_width=10 filled empty bar="" reset_block=""
  filled=$(( pct_int * bar_width / 100 ))
  empty=$(( bar_width - filled ))
  for (( i=0; i<filled; i++ )); do bar="${bar}█"; done
  for (( i=0; i<empty; i++ )); do bar="${bar}░"; done
  if [ -n "$resets_at" ]; then
    local now secs_left hrs mins days reset_text reset_color
    now=$(date +%s)
    secs_left=$(( resets_at - now ))
    if [ "$secs_left" -gt 0 ]; then
      days=$(( secs_left / 86400 ))
      hrs=$(( (secs_left % 86400) / 3600 ))
      mins=$(( (secs_left % 3600) / 60 ))
      if [ "$days" -gt 0 ]; then
        reset_text=$(printf "↻%dd%02dh" "$days" "$hrs")
      elif [ "$hrs" -gt 0 ]; then
        reset_text=$(printf "↻%dh%02dm" "$hrs" "$mins")
      else
        reset_text=$(printf "↻%dm" "$mins")
      fi
      if [ -n "$alert_secs" ] && [ "$secs_left" -le "$alert_secs" ]; then
        reset_color="$C_BAR_ALERT"
      elif [ -n "$crit_secs" ] && [ "$secs_left" -le "$crit_secs" ]; then
        reset_color="$C_BAR_CRIT"
      elif [ -n "$warn_secs" ] && [ "$secs_left" -le "$warn_secs" ]; then
        reset_color="$C_BAR_WARN"
      else
        reset_color="$color"
      fi
      reset_block=$(printf " ${reset_color}%s${C_RESET}" "$reset_text")
    fi
  fi
  local prefix=""
  [ -n "$label" ] && prefix="${label} "
  printf "${color}%s[%s] %d%%${C_RESET}%s" "$prefix" "$bar" "$pct_int" "$reset_block"
}

# 5h color: <50 dim, 50-79 gold, 80-94 coral-red, 95+ alert
plan_color="$C_BAR_OK"
if [ -n "$plan_pct" ]; then
  plan_int=${plan_pct%.*}
  if [ "$plan_int" -ge 95 ]; then plan_color="$C_BAR_ALERT"
  elif [ "$plan_int" -ge 80 ]; then plan_color="$C_BAR_CRIT"
  elif [ "$plan_int" -ge 50 ]; then plan_color="$C_BAR_WARN"; fi
fi

# Weekly window: only shown when >=75%
# 7d color: 75-79 dim, 80-89 gold, 90-94 coral-red, 95+ alert
week_str=""
plan_label=""
if [ -n "$week_pct" ]; then
  week_int=${week_pct%.*}
  if [ "$week_int" -ge 75 ]; then
    if [ "$week_int" -ge 95 ]; then week_color="$C_BAR_ALERT"
    elif [ "$week_int" -ge 90 ]; then week_color="$C_BAR_CRIT"
    elif [ "$week_int" -ge 80 ]; then week_color="$C_BAR_WARN"
    else week_color="$C_BAR_OK"; fi
    # 7d reset thresholds: warn=1d, crit=8h, alert=1h
    week_str=$(render_plan "7d" "$week_pct" "$week_resets_at" "$week_color" 86400 28800 3600)
    plan_label="5h"
  fi
fi
# 5h reset thresholds: warn=1h, crit=30m, alert=5m
plan_str=$(render_plan "$plan_label" "$plan_pct" "$plan_resets_at" "$plan_color" 3600 1800 300)

# --- Build output ---
sep="${C_DIM} | ${C_RESET}"
parts="${C_DIR}${dir_name}${C_RESET}"

[ -n "$wt_name" ] && parts="${parts}${sep}${C_WORKTREE}⑂ ${wt_name}${C_RESET}"

if [ -n "$branch" ]; then
  if [ -n "$JIRA_BASE_URL" ] && [[ "$branch" =~ ^${JIRA_TICKET_PREFIX}-[0-9]+ ]]; then
    jira_id="${BASH_REMATCH[0]}"
    jira_link=$(printf "\033]8;;%s/%s\007${C_BRANCH}%s${C_RESET}\033]8;;\007" "$JIRA_BASE_URL" "$jira_id" "$branch")
    parts="${parts}${sep}${jira_link}${dirty}"
  else
    parts="${parts}${sep}${C_BRANCH}${branch}${C_RESET}${dirty}"
  fi
fi

[ -n "$ctx_str" ] && parts="${parts}${sep}${ctx_str}"
parts="${parts}${sep}${C_MODEL}${model}${C_RESET}"
[ -n "$usage_str" ] && parts="${parts}${sep}${usage_str}"
[ -n "$plan_str" ] && parts="${parts}${sep}${plan_str}"
[ -n "$week_str" ] && parts="${parts}${sep}${week_str}"

printf "%b\n" "$parts"
